import{_ as l,o,c as e,a2 as t}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"在线更新","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/update.md","filePath":"deploy/update.md","lastUpdated":1786505997000}'),i={name:"deploy/update.md"};function r(s,a,n,d,c,h){return o(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="在线更新" tabindex="-1">在线更新 <a class="header-anchor" href="#在线更新" aria-label="Permalink to &quot;在线更新&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：怎么在后台一键升级到新版本，更新后自动重启。</p></blockquote><p>V3 内置<strong>在线更新</strong>机制，小版本升级无需 SSH 登录服务器、无需重新部署。</p><h2 id="检测更新" tabindex="-1">检测更新 <a class="header-anchor" href="#检测更新" aria-label="Permalink to &quot;检测更新&quot;">​</a></h2><p>登录管理后台 → <strong>系统更新</strong>：</p><ol><li>点击「检测更新」，系统向云端查询最新版本。</li><li>如有新版本，会显示版本号、更新内容、更新文件数量和大小。</li><li>确认后点击「立即更新」。</li></ol><h2 id="更新过程" tabindex="-1">更新过程 <a class="header-anchor" href="#更新过程" aria-label="Permalink to &quot;更新过程&quot;">​</a></h2><p>更新会：</p><ol><li><strong>增量下载</strong>更新包（只下载变化的文件）。</li><li>替换变化的文件。</li><li>如新版本附带 SQL 迁移脚本，自动执行。</li><li><strong>自动重启</strong>服务，加载新代码。</li></ol><div class="tip custom-block"><p class="custom-block-title">更新期间短暂中断</p><p>更新完成后服务会自动重启，浏览器可能短暂断开（几秒），属正常现象。重启完成后刷新页面即可。</p></div><h2 id="自动重启" tabindex="-1">自动重启 <a class="header-anchor" href="#自动重启" aria-label="Permalink to &quot;自动重启&quot;">​</a></h2><p>更新后必须重启才能加载新代码（尤其是编译保护的模块）。V3 支持：</p><ul><li><strong>自动重启</strong>：更新完成后，服务在几秒后自动重启（默认开启）。</li><li><strong>手动重启</strong>：如果你关闭了自动重启，需要手动执行 <code>docker compose restart</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">为什么必须重启</p><p>受保护的代码模块在进程启动时加载，运行中替换文件不会立即生效。重启是让新代码生效的必要步骤。</p></div><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><ul><li>系统版本号在后台首页和系统更新页可见。</li><li>云端返回的版本号 &gt; 本地版本号时，提示有更新。</li><li>版本号采用语义化版本（如 <code>3.0.5</code>）。</li></ul><h2 id="更新失败怎么办" tabindex="-1">更新失败怎么办 <a class="header-anchor" href="#更新失败怎么办" aria-label="Permalink to &quot;更新失败怎么办&quot;">​</a></h2><ul><li><strong>网络问题</strong>：检查服务器能否访问授权云（更新包从云端下载）。</li><li><strong>磁盘空间不足</strong>：清理后重试。</li><li><strong>权限问题</strong>：确认部署目录可写（Docker volume 挂载方式天然可写）。</li></ul><p>更新失败不会破坏现有系统——文件替换是原子操作，失败时保持旧版本运行。</p><h2 id="大版本升级" tabindex="-1">大版本升级 <a class="header-anchor" href="#大版本升级" aria-label="Permalink to &quot;大版本升级&quot;">​</a></h2><p>跨大版本（如 3.x → 4.x）或镜像本身变更时，建议用 <code>install.sh</code> 重新部署而非在线更新：</p><ul><li>数据在 volume 持久化，重新部署不丢数据。</li><li>详见 <a href="./docker#升级部署">Docker 部署 · 升级</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>日常运维 → <a href="./ops">运维与备份</a></li></ul>',24)])])}const m=l(i,[["render",r]]);export{u as __pageData,m as default};
